'use strict';
let contentReadOnly=false;let noteBoard='',noteLayout='columns',noteZoom=1,noteDrag=null;
const CARD_TYPES={note:'Ghi chú',heading:'Tiêu đề',link:'Liên kết',todo:'Checklist',board:'Bảng con',image:'Hình ảnh',video:'Video',audio:'Âm thanh',document:'Tài liệu',color:'Bảng màu',table:'Bảng dữ liệu',comment:'Nhận xét',line:'Đường nối',sketch:'Phác thảo',map:'Bản đồ'};
const safeId=v=>esc(v),fileURL=id=>'/api/assets/'+encodeURIComponent(id)+'?preview=1';
function boardChildren(id){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const n of data.notes||[])if(ids.has(n.boardId||'')&&!ids.has(n.id)){ids.add(n.id);changed=true;}}return ids;}
function noteContent(n){const content='<p>'+esc(n.text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')+'</p>';let media='';if(n.fileId){const src=fileURL(n.fileId);if(n.type==='image')media=`<img class="board-media" src="${src}" alt="${esc(n.title)}" loading="lazy">`;else if(n.type==='audio')media=`<audio class="board-media" controls preload="none" src="${src}"></audio>`;else if(n.type==='video')media=`<video class="board-media" controls preload="metadata" src="${src}"></video>`;else media=`<a href="/api/assets/${encodeURIComponent(n.fileId)}">Tải tài liệu ↗</a>`;}
if(n.type==='board')return `<button class="board-open" data-open-board="${safeId(n.id)}">▦ ${esc(n.title)}<small>${(data.notes||[]).filter(x=>x.boardId===n.id).length} mục · Mở bảng →</small></button>`;
if(n.type==='todo')return (n.items||[]).map((item,i)=>`<label class="check-row"><input type="checkbox" data-note-check="${safeId(n.id)}" data-item="${i}" ${item.done?'checked':''}><span>${esc(item.text)}</span></label>`).join('');
if(n.type==='table')return '<div class="table-wrap"><table class="content-table">'+n.text.split('\n').map(row=>'<tr>'+row.split('|').map(cell=>'<td>'+esc(cell.trim())+'</td>').join('')+'</tr>').join('')+'</table></div>';
if(n.type==='color')return `<div class="color-swatch" style="background:${n.color}">${n.color}</div>`+content;
return media+(n.sketch?`<img class="board-media" alt="Phác thảo" src="${n.sketch}">`:'')+content+(n.url?`<a href="${esc(n.url)}" rel="noopener noreferrer" target="_blank">${n.type==='map'?'Mở bản đồ':'Mở liên kết'} ↗</a>`:'');}
function contentCard(n,i){return `<article class="content-card ${n.type==='heading'?'heading-card':''}" data-card="${safeId(n.id)}" style="--card-color:${n.color};${noteLayout==='canvas'?`left:${n.x??(i%4)*310+24}px;top:${n.y??Math.floor(i/4)*300+24}px;width:${n.width||280}px;`:''}"><div class="card-handle" draggable="true" data-note-drag="${safeId(n.id)}" tabindex="0" aria-label="Di chuyển ${esc(n.title)}"><span>${esc(CARD_TYPES[n.type]||'Ghi chú')}</span><span>⠿</span></div>${n.type!=='board'?`<h3>${esc(n.title)}</h3>`:''}${noteContent(n)}<div class="content-actions"><button type="button" data-note-edit="${safeId(n.id)}">Sửa</button><button type="button" data-note-copy="${safeId(n.id)}">Nhân bản</button><button type="button" data-note-files="${safeId(n.id)}">Tệp</button><button type="button" data-note-delete="${safeId(n.id)}">Thùng rác</button></div></article>`;}
notesPage=function(){const notes=(data.notes||[]).filter(n=>(n.boardId||'')===noteBoard&&(n.title+' '+n.text).toLowerCase().includes(query.toLowerCase())),current=(data.notes||[]).find(n=>n.id===noteBoard),groups=[...new Set(['Chưa phân nhóm',...notes.map(n=>n.group||'Chưa phân nhóm')])];return heading('CONTENT STUDIO',esc(current?.title||'Bảng nội dung'),'Thu thập, kết nối và phát triển ý tưởng.')+`<div class="content-top"><button class="btn" data-open-board="${safeId(current?.boardId||'')}">← ${noteBoard?'Bảng cha':'Trang gốc'}</button><select id="note-layout" aria-label="Chế độ bảng"><option value="columns" ${noteLayout==='columns'?'selected':''}>Cột nội dung</option><option value="canvas" ${noteLayout==='canvas'?'selected':''}>Bảng tự do</option><option value="grid" ${noteLayout==='grid'?'selected':''}>Lưới</option></select><button class="btn" data-note-column>+ Cột</button><button class="btn" data-note-template>Mẫu content</button><button class="btn" data-board-share>Chia sẻ</button><button class="btn" data-board-export>Xuất Markdown</button><button class="btn" data-board-print>In / PDF</button><button class="btn" data-view="trash">Thùng rác</button>${noteLayout==='canvas'?'<button class="btn" data-zoom="-0.1">−</button><span>'+Math.round(noteZoom*100)+'%</span><button class="btn" data-zoom="0.1">+</button>':''}</div><div class="content-studio"><aside class="content-toolbar">${Object.entries(CARD_TYPES).map(([type,label])=>`<button class="btn" data-new-card="${type}">${label}</button>`).join('')}</aside><div class="content-viewport"><div class="content-surface ${noteLayout}" style="${noteLayout==='canvas'?`transform:scale(${noteZoom});transform-origin:top left;`:''}">${noteLayout==='columns'?groups.map(group=>`<section class="content-column" data-note-drop="${esc(group)}"><h3>${esc(group)} <small>${notes.filter(n=>(n.group||'Chưa phân nhóm')===group).length} mục</small></h3>${notes.filter(n=>(n.group||'Chưa phân nhóm')===group).map(contentCard).join('')}</section>`).join(''):notes.map(contentCard).join('')}${noteLayout==='canvas'?noteLines(notes):''}</div></div></div>`;};
function noteLines(notes){return '<svg class="board-lines" width="4000" height="3000" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#7950c8"/></marker></defs>'+notes.filter(n=>n.type==='line').map(n=>{const a=notes.find(x=>x.id===n.from),b=notes.find(x=>x.id===n.to);if(!a||!b)return '';const ai=notes.indexOf(a),bi=notes.indexOf(b);return `<line x1="${(a.x??ai%4*310+24)+140}" y1="${(a.y??Math.floor(ai/4)*300+24)+70}" x2="${(b.x??bi%4*310+24)+140}" y2="${(b.y??Math.floor(bi/4)*300+24)+70}" stroke="${n.color}" stroke-width="2" marker-end="url(#arrow)"/>`;}).join('')+'</svg>';}
const basicNoteForm=noteForm;
noteForm=function(n,kind='note'){basicNoteForm(n);const type=n?.type||kind,id=n?.id,blocked=n?boardChildren(n.id):new Set();$('#editor-body').insertAdjacentHTML('afterbegin',`<div class="fields-row"><label class="field">Loại nội dung<select name="cardType">${Object.entries(CARD_TYPES).map(([k,v])=>`<option value="${k}" ${type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Bảng chứa<select name="boardId"><option value="">Trang gốc</option>${(data.notes||[]).filter(x=>x.type==='board'&&!blocked.has(x.id)).map(x=>`<option value="${safeId(x.id)}" ${(n?.boardId??noteBoard)===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></div><p class="help-copy">Checklist: mỗi dòng một việc. Bảng dữ liệu: mỗi dòng một hàng, dùng | ngăn cột. **Chữ đậm** được hỗ trợ. Ảnh/âm thanh/video/tài liệu: lưu thẻ rồi mở Tệp.</p><div class="fields-row">${field('Chiều rộng thẻ (bảng tự do)','cardWidth',n?.width||280,'number')}<label class="check-row"><input type="checkbox" name="locked" ${n?.locked?'checked':''}>Khóa vị trí</label></div><label class="field">Nối từ thẻ<select name="from"><option value="">Chọn thẻ</option>${(data.notes||[]).filter(x=>(x.boardId||'')===noteBoard&&x.type!=='line').map(x=>`<option value="${x.id}" ${n?.from===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="field">Đến thẻ<select name="to"><option value="">Chọn thẻ</option>${(data.notes||[]).filter(x=>(x.boardId||'')===noteBoard&&x.type!=='line').map(x=>`<option value="${x.id}" ${n?.to===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`);
if(type==='todo')$('#editor-body textarea[name=text]').value=(n?.items||[]).map(x=>x.text).join('\n');const original=$('#editor-form').onsubmit;$('#editor-form').onsubmit=e=>{const fd=new FormData(e.target),title=fd.get('title').trim();if(!title)return;const before=(data.notes||[]).length;original(e);if($('#editor').open)return;const saved=id?data.notes.find(x=>x.id===id):data.notes.at(-1);if(!saved||!id&&(data.notes.length===before))return;const oldItems=n?.items||[];Object.assign(saved,{type:fd.get('cardType'),boardId:fd.get('boardId'),width:Math.min(800,Math.max(200,Number(fd.get('cardWidth'))||280)),locked:fd.get('locked')==='on',from:fd.get('from'),to:fd.get('to')});if(saved.type==='todo')saved.items=saved.text.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,200).map(text=>({text:text.slice(0,300),done:oldItems.find(x=>x.text===text)?.done||false}));save();render();};};
function moveToTrash(before){data.trash||=structuredClone(before.trash||[]);const put=(kind,value,parent)=>data.trash.push({id:uid(),at:Date.now(),kind,name:value.title||value.name||value.text||'Dữ liệu',payload:JSON.stringify(value),parent:parent?JSON.stringify(parent):''});for(const p of before.projects){const next=data.projects.find(x=>x.id===p.id);if(!next){put('project',p);continue;}for(const t of p.tasks){const nt=next.tasks.find(x=>x.id===t.id);if(!nt){put('task',t,{...p,tasks:[]});continue;}for(const c of t.checks)if(!nt.checks.some(x=>x.id===c.id))put('check',c,{project:{...p,tasks:[]},task:{...t,checks:[]}});}}for(const n of before.notes||[])if(!(data.notes||[]).some(x=>x.id===n.id))put('note',n);}
const oldConfirmDelete=confirmDelete;confirmDelete=function(kind,fn){oldConfirmDelete(kind,()=>{const before=structuredClone(data);fn();moveToTrash(before);});$('#editor-body .help-copy').textContent='Dữ liệu chuyển vào Thùng rác, có thể khôi phục trong 30 ngày. Sau đó hệ thống tự dọn.';};
function trashPage(){return heading('KHÔI PHỤC DỮ LIỆU','Thùng rác','Giữ 30 ngày kể từ lúc xóa. Tệp và ghi chú chỉ bị dọn sau thời hạn này.')+`<section class="panel">${(data.trash||[]).map(x=>`<div class="trash-row"><div><strong>${esc(x.name)}</strong><small>${new Date(x.at).toLocaleString('vi-VN')} · ${Math.max(0,30-Math.floor((Date.now()-x.at)/86400000))} ngày còn lại</small></div><button class="btn" data-restore-item="${safeId(x.id)}">Khôi phục</button></div>`).join('')||'<p>Không có dữ liệu đã xóa.</p>'}</section><section class="panel"><h3>Tệp trong Thùng rác</h3><div id="file-trash-list">Đang tải…</div></section>`;}
async function loadTrashFiles(){try{const r=await requestAPI('assets/trash');if(!$('#file-trash-list'))return;$('#file-trash-list').innerHTML=[...r.files.map(f=>({...f,legacy:false})),...r.legacy.map(f=>({...f,legacy:true}))].map(f=>`<div class="trash-row"><span>${esc(f.name)} · ${formatSize(f.size)}</span><button class="btn" data-restore-file="${f.id}" data-legacy="${f.legacy}">Khôi phục</button></div>`).join('')||'Không có tệp đã xóa.';}catch(e){if($('#file-trash-list'))$('#file-trash-list').textContent=e.message;}}
function restoreItem(id){const record=data.trash?.find(x=>x.id===id);if(!record)return;const next=structuredClone(data),value=JSON.parse(record.payload),parent=record.parent?JSON.parse(record.parent):null;let target;if(record.kind==='project'){if(next.projects.some(x=>x.id===value.id))return notify('Dự án đã tồn tại.');next.projects.push(value);}if(record.kind==='note'){next.notes||=[];if(next.notes.some(x=>x.id===value.id))return notify('Ghi chú đã tồn tại.');if(value.boardId&&!next.notes.some(x=>x.id===value.boardId))value.boardId='';next.notes.push(value);if(value.type==='board'){const ids=new Set([value.id]);let changed=true;while(changed){changed=false;for(const r of next.trash){if(r.kind!=='note'||ids.has(JSON.parse(r.payload).id))continue;const child=JSON.parse(r.payload);if(ids.has(child.boardId)&&!next.notes.some(n=>n.id===child.id)){next.notes.push(child);ids.add(child.id);changed=true;}}}next.trash=next.trash.filter(r=>r.kind!=='note'||!ids.has(JSON.parse(r.payload).id));}}if(record.kind==='task'){target=next.projects.find(x=>x.id===parent.id);if(!target){target=parent;next.projects.push(target);}if(target.tasks.some(x=>x.id===value.id))return notify('Task đã tồn tại.');target.tasks.push(value);}if(record.kind==='check'){target=next.projects.find(x=>x.id===parent.project.id);if(!target){target=parent.project;next.projects.push(target);}let task=target.tasks.find(x=>x.id===parent.task.id);if(!task){task=parent.task;target.tasks.push(task);}if(!task.checks.some(x=>x.id===value.id))task.checks.push(value);syncChecks(task);}next.trash=next.trash.filter(x=>x.id!==id);if(!valid(next))return notify('Không thể khôi phục: dữ liệu vượt giới hạn hoặc không tương thích.');data=next;save();render();notify('Đã khôi phục.');}
function formatSize(n){return n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB';}
async function assetPanel(scope,legacy){if(dirty){await flushCloud();if(dirty)return notify('Cần đồng bộ trước khi tải tệp.');}modal('<h2>Kho tệp riêng tư</h2><p>Tải từng phần 64 MiB · tối đa 625 GiB/tệp. Dung lượng lớn phụ thuộc kết nối và gói Cloudflare R2.</p><input id="large-file" type="file" multiple aria-label="Chọn tệp"><progress id="upload-progress" value="0" max="100"></progress><p id="upload-status" role="status"></p><button class="btn" type="button" id="cancel-upload" hidden>Hủy tải</button><div id="asset-list"></div>',null,true);let cancelled=false,busy=false;const refresh=async()=>{const r=await requestAPI('assets?scope='+encodeURIComponent(scope));let files=r.files;if(legacy){const l=await requestAPI('files?project='+encodeURIComponent(legacy.p)+'&task='+encodeURIComponent(legacy.t||''));files=[...files,...l.files.map(f=>({...f,legacy:true}))];}if(!$('#asset-list'))return;$('#asset-list').innerHTML=files.map(f=>`<div class="trash-row"><a href="/api/${f.legacy?'files':'assets'}/${f.id}">${esc(f.name)}</a><small>${formatSize(f.size)}</small><button class="btn" type="button" data-trash-file="${f.id}" data-legacy="${!!f.legacy}">Thùng rác</button>${scope.startsWith('note:')&&!f.legacy?`<button class="btn" type="button" data-use-file="${f.id}" data-note-id="${safeId(scope.slice(5))}">Dùng trong thẻ</button>`:''}</div>`).join('')||'<p>Chưa có tệp.</p>';};await refresh();$('#cancel-upload').onclick=()=>cancelled=true;$('#large-file').onchange=async e=>{if(busy)return;busy=true;cancelled=false;e.target.disabled=true;$('#cancel-upload').hidden=false;try{for(const file of e.target.files){if(cancelled)break;if(!file.size||file.size>64*1024*1024*10000)throw Error('Tệp rỗng hoặc vượt 625 GiB.');let id;try{const start=await requestAPI('assets/start','POST',{name:file.name,size:file.size,mime:file.type,scope});id=start.id;let part=0;for(let offset=0;offset<file.size;offset+=start.chunk){if(cancelled)throw Error('Đã hủy tải.');const chunk=file.slice(offset,offset+start.chunk);let ok=false;part++;for(let attempt=0;attempt<3;attempt++){try{const response=await fetch('/api/assets/'+id+'/part?n='+part,{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:chunk});if(!response.ok)throw Error((await response.json()).error||'Tải thất bại.');ok=true;break;}catch(err){if(attempt===2)throw err;}}if(ok&&$('#upload-status')){$('#upload-progress').value=Math.round(Math.min(offset+chunk.size,file.size)/file.size*100);$('#upload-status').textContent=file.name+' · '+$('#upload-progress').value+'%';}}await requestAPI('assets/'+id+'/complete','POST',{});await refresh();}catch(err){if(id)await requestAPI('assets/'+id+'/abort','POST',{}).catch(()=>{});throw err;}}if($('#upload-status'))$('#upload-status').textContent=cancelled?'Đã hủy.':'Đã tải xong.';}catch(err){if($('#upload-status'))$('#upload-status').textContent=err.message;}finally{busy=false;if($('#large-file'))$('#large-file').disabled=false;if($('#cancel-upload'))$('#cancel-upload').hidden=true;}};$('#asset-list').onclick=async e=>{const el=e.target.closest('[data-trash-file],[data-use-file]');if(!el)return;try{if(el.dataset.trashFile){await requestAPI((el.dataset.legacy==='true'?'legacy-files/':'assets/')+el.dataset.trashFile+'/trash','POST',{});await refresh();}else{const n=data.notes.find(x=>x.id===el.dataset.noteId);n.fileId=el.dataset.useFile;save();$('#editor').close();render();}}catch(err){notify(err.message);}};}
filePanel=(p,t)=>assetPanel('project:'+p.id+(t?':task:'+t.id:''),{p:p.id,t:t?.id});
const trashNav=document.createElement('button');trashNav.className='nav';trashNav.dataset.view='trash';trashNav.innerHTML='<span>'+svgIcon('versions')+'</span>Thùng rác';document.querySelector('.sidebar nav').append(trashNav);
const beforeContentRender=render;render=function(){beforeContentRender();if(view==='trash'){$('#main').innerHTML=trashPage();loadTrashFiles();}if(contentReadOnly){document.querySelectorAll('.content-card input').forEach(el=>el.disabled=true);document.querySelectorAll('.content-toolbar,.content-actions').forEach(el=>el.hidden=true);$('#main').insertAdjacentHTML('afterbegin','<p class="share-notice">Bản chia sẻ chỉ xem · Tệp riêng tư không được chia sẻ.</p>');}if(view==='notes'){$('#crumb').textContent='Ghi chú';$('#search').placeholder='Tìm trong bảng…';}else $('#search').placeholder='Tìm công việc…';};
$('#search').addEventListener('input',e=>{if(noteSearchActive){view='notes';query=e.target.value;render();}},true);let noteSearchActive=false;document.addEventListener('focusin',e=>{if(e.target.id==='search')noteSearchActive=view==='notes';});
document.addEventListener('change',e=>{if(e.target.id==='note-layout'){noteLayout=e.target.value;render();}if(e.target.dataset.noteCheck){const n=data.notes.find(x=>x.id===e.target.dataset.noteCheck);n.items[Number(e.target.dataset.item)].done=e.target.checked;save();}});
document.addEventListener('dragstart',e=>{const handle=e.target.closest('[data-note-drag]');if(handle){noteDrag=handle.dataset.noteDrag;e.dataTransfer.setData('text/note-id',noteDrag);}});document.addEventListener('dragover',e=>{if(noteDrag&&e.target.closest('[data-note-drop],[data-card]'))e.preventDefault();});document.addEventListener('drop',e=>{if(!noteDrag)return;const n=data.notes.find(x=>x.id===noteDrag),column=e.target.closest('[data-note-drop]'),card=e.target.closest('[data-card]');if(!n.locked&&column){n.group=column.dataset.noteDrop==='Chưa phân nhóm'?'':column.dataset.noteDrop;if(card&&card.dataset.card!==n.id){data.notes=data.notes.filter(x=>x.id!==n.id);data.notes.splice(data.notes.findIndex(x=>x.id===card.dataset.card),0,n);}save();render();}noteDrag=null;});document.addEventListener('dragend',()=>noteDrag=null);
let canvasMove=null;document.addEventListener('pointerdown',e=>{if(noteLayout!=='canvas')return;const handle=e.target.closest('[data-note-drag]');if(!handle)return;const n=data.notes.find(x=>x.id===handle.dataset.noteDrag);if(n.locked)return;const card=handle.closest('[data-card]');canvasMove={n,card,x:e.clientX,y:e.clientY,left:parseFloat(card.style.left),top:parseFloat(card.style.top)};handle.draggable=false;handle.setPointerCapture(e.pointerId);e.preventDefault();});document.addEventListener('pointermove',e=>{if(!canvasMove)return;const m=canvasMove;m.n.x=Math.max(0,Math.min(3600,m.left+(e.clientX-m.x)/noteZoom));m.n.y=Math.max(0,Math.min(2600,m.top+(e.clientY-m.y)/noteZoom));m.card.style.left=m.n.x+'px';m.card.style.top=m.n.y+'px';});document.addEventListener('pointerup',()=>{if(canvasMove){canvasMove=null;save();render();}});document.addEventListener('pointercancel',()=>{if(canvasMove){canvasMove=null;save();render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-new-card],[data-open-board],[data-note-copy],[data-note-files],[data-restore-item],[data-restore-file],[data-note-column],[data-note-template],[data-board-export],[data-board-print],[data-zoom]');if(!b)return;try{if(b.dataset.newCard)noteForm(null,b.dataset.newCard);if(b.hasAttribute('data-open-board')){noteBoard=b.dataset.openBoard;go('notes');}if(b.dataset.noteCopy){if(data.notes.length>=500)return notify('Tối đa 500 thẻ.');const n=structuredClone(data.notes.find(x=>x.id===b.dataset.noteCopy));n.id=uid();n.title+=' (bản sao)';n.x=(n.x||0)+30;n.y=(n.y||0)+30;data.notes.push(n);save();render();}if(b.dataset.noteFiles)await assetPanel('note:'+b.dataset.noteFiles);if(b.dataset.restoreItem)restoreItem(b.dataset.restoreItem);if(b.dataset.restoreFile){await requestAPI((b.dataset.legacy==='true'?'legacy-files/':'assets/')+b.dataset.restoreFile+'/restore','POST',{});await loadTrashFiles();}if(b.hasAttribute('data-note-column'))modal('<h2>Thêm cột</h2>'+field('Tên cột','name','','text',true,80),fd=>{const name=fd.get('name').trim();if(!name)return;data.notes||=[];if(data.notes.length>=500)return notify('Tối đa 500 thẻ.');data.notes.push({id:uid(),title:name,text:'',group:name,boardId:noteBoard,type:'heading',color:'#7950c8',url:''});save();$('#editor').close();render();});if(b.hasAttribute('data-note-template')){data.notes||=[];if(data.notes.length>496)return notify('Không đủ chỗ cho mẫu.');for(const [group,text] of [['Ý tưởng','Chủ đề · Độc giả · Thông điệp'],['Nghiên cứu','Nguồn tham khảo · Insight'],['Sản xuất','Dàn ý\nViết bản nháp\nBiên tập'],['Xuất bản','Kênh đăng · Ngày đăng · Kết quả']])data.notes.push({id:uid(),title:group,text,group,boardId:noteBoard,type:'note',color:'#7950c8',url:''});save();render();}if(b.hasAttribute('data-board-export')){const notes=data.notes.filter(n=>(n.boardId||'')===noteBoard),text=notes.map(n=>'## '+n.title+'\n\n'+n.text+(n.url?'\n'+n.url:'')+(n.items?'\n'+n.items.map(i=>'- ['+(i.done?'x':' ')+'] '+i.text).join('\n'):'')).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download='content-board.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(b.hasAttribute('data-board-print'))window.print();if(b.dataset.zoom){noteZoom=Math.max(.4,Math.min(1.5,noteZoom+Number(b.dataset.zoom)));render();}}catch(err){notify(err.message);}});
render();

document.addEventListener('click',async e=>{if(!e.target.closest('[data-board-share]'))return;modal('<h2>Chia sẻ bảng nội dung</h2><p>Tạo bản chụp chỉ xem, có hiệu lực 7 ngày. Người có liên kết xem được nội dung và bản phác thảo; tệp đính kèm vẫn riêng tư. Thay đổi sau khi tạo không cập nhật bản chia sẻ.</p><button type="button" class="btn primary" id="create-share">Tạo liên kết chỉ xem</button><button type="button" class="btn" id="revoke-share">Thu hồi tất cả liên kết của tôi</button><p id="share-status" role="status"></p>',null,true);$('#create-share').onclick=async()=>{try{await flushCloud();if(dirty)throw Error('Hãy đợi đồng bộ xong.');const r=await requestAPI('board-share','POST',{boardId:noteBoard});$('#share-status').innerHTML='<a href="'+esc(r.url)+'">'+esc(r.url)+'</a>';}catch(error){$('#share-status').textContent=error.message;}};$('#revoke-share').onclick=async()=>{try{await requestAPI('board-share','POST',{revoke:true});$('#share-status').textContent='Đã thu hồi các liên kết.';}catch(error){$('#share-status').textContent=error.message;}};});
document.addEventListener('click',e=>{if(!contentReadOnly)return;const target=e.target.closest('button,input,select');if(target&&!target.matches('[data-open-board],[data-zoom],#note-layout,[data-board-export],[data-board-print]')){e.preventDefault();e.stopImmediatePropagation();}},true);document.addEventListener('pointerdown',e=>{if(contentReadOnly&&e.target.closest('[data-note-drag]'))e.stopImmediatePropagation();},true);document.addEventListener('dragstart',e=>{if(contentReadOnly){e.preventDefault();e.stopImmediatePropagation();}},true);
